/**
 * Preserve every generated file for previously admitted Python copied fixtures.
 *
 * @file
 */
import assert from "node:assert/strict";
import { canonicalJson, sha256 } from "../../src/capsule/node.mjs";
import { callableReviewedIr } from "./callable-fixture.mjs";
import { pythonCallableSignatures } from "./python-callable-fixture.mjs";
import { collectionReviewedIr } from "./collection-fixture.mjs";
import { compoundReviewedIr } from "./compound-source-fixture.mjs";
import { listReviewedIr } from "./list-fixture.mjs";
import { nativeAliasReviewedIr } from "./native-alias-fixture.mjs";
import { cVariantReviewedIr } from "./c-variant-fixture.mjs";
import { moduleAtProducer } from "./producer-module.mjs";

export const pythonStructuredRegressionFixtures = {
	callables: () => callableReviewedIr(pythonCallableSignatures)
	, collections: collectionReviewedIr, compounds: compoundReviewedIr
	, lists: listReviewedIr, aliases: nativeAliasReviewedIr
	, variants: cVariantReviewedIr
};
export const pythonStructuredCodegenProducer
	= "cbb6fecce821a9a9fef3c06ab93b9c46786c9323";

/**
 * Compare all generated bytes with an independently rendered predecessor.
 *
 * @param record - Frozen source identities and generated-file observations.
 */
export const assertPythonStructuredCodegenRegression = async record => {
	assert.equal(record.schemaVersion, 1); assert.equal(record.planNode, 1219);
	assert.equal(record.kind, "python-structured-codegen-regression");
	assert.match(record.baselineRevision, /^[a-f0-9]{40}$/);
	const producer = await moduleAtProducer(
		pythonStructuredCodegenProducer, "src/backends/python/copied-values.mjs");
	assert.deepEqual(record.fixtures.map(item => item.name), Object.keys(pythonStructuredRegressionFixtures));
	for(const fixture of record.fixtures)
	{
		const ir = pythonStructuredRegressionFixtures[fixture.name]();
		assert.equal(fixture.bindingIrSha256, sha256(canonicalJson(ir)));
		const files = producer.generateCopiedPythonPackage(ir);
		assert.deepEqual(fixture.files, Object.fromEntries(Object.entries(files).map(([path, source]) => [path, { bytes: Buffer.byteLength(source), sha256: sha256(source) }])));
		assert.equal(fixture.identicalToPredecessor, true);
	}
};
